import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.reduce.js";
import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import api from '../../services/api';
export default {
  name: 'StoreReports',
  data() {
    const today = new Date();
    const to = today.toISOString().slice(0, 10);
    const fromDate = new Date();
    fromDate.setDate(today.getDate() - 30);
    const from = fromDate.toISOString().slice(0, 10);
    return {
      from,
      to,
      period: 'monthly',
      daily: [],
      orders: [],
      latestSubmissionId: null
    };
  },
  computed: {
    deliveredRevenue() {
      return this.daily.filter(d => String(d.channel) === 'delivered').reduce((sum, d) => sum + Number(d.revenue || 0), 0);
    },
    pickupRevenue() {
      return this.daily.filter(d => String(d.channel) === 'pickup').reduce((sum, d) => sum + Number(d.revenue || 0), 0);
    }
  },
  created() {
    this.fetchAll();
  },
  methods: {
    channelLabel(channel) {
      return String(channel) === 'pickup' ? 'Pickup' : 'Delivered';
    },
    async fetchAll() {
      const params = {
        from: this.from,
        to: this.to
      };
      const dailyRes = await api.get('/store/reports/sales', {
        params
      });
      this.daily = dailyRes.data || [];
      const ordersRes = await api.get('/store/reports/orders', {
        params
      });
      this.orders = ordersRes.data || [];
    },
    async generatePdfReport() {
      try {
        const res = await api.post('/store/reports/generate-pdf', {
          period: this.period,
          from: this.from,
          to: this.to
        }, {
          responseType: 'blob'
        });
        const disposition = res.headers?.['content-disposition'] || '';
        const match = disposition.match(/filename="?([^";]+)"?/i);
        const filename = match && match[1] ? match[1] : `sales_report_${this.from}_to_${this.to}.pdf`;
        const mimeType = res.headers?.['content-type'] || 'application/pdf';
        const blob = new Blob([res.data], {
          type: mimeType
        });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = filename;
        anchor.click();
        URL.revokeObjectURL(url);
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to generate PDF report');
      }
    },
    async downloadExcelForm() {
      try {
        const res = await api.get('/store/reports/da-excel-form', {
          responseType: 'blob'
        });
        const disposition = res.headers?.['content-disposition'] || '';
        const m = disposition.match(/filename="?([^";]+)"?/i);
        const filename = m && m[1] ? m[1] : `KADIWA-Sales-Report-Form_${new Date().toISOString().slice(0, 10)}.xlsx`;
        const mimeType = res.headers?.['content-type'] || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
        const blob = new Blob([res.data], {
          type: mimeType
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        a.click();
        URL.revokeObjectURL(url);
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to download Excel form');
      }
    },
    async submitReportToDa() {
      if (!confirm('Are you sure you want to submit this report to DA? This will be recorded in the system.')) return;
      try {
        const {
          data
        } = await api.post('/store/reports/submit-to-da', {
          period: this.period,
          from: this.from,
          to: this.to
        });
        alert('Report submitted to DA successfully! Submission ID: ' + data?.submission_id);
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to submit report to DA');
      }
    }
  }
};
